UPDATE ntss.sys_facility_setting SET setting_name='治療予定日変更時 検査予定変更機能', option_value='[{"id":"1","name":"1:検査依頼を治療予定日に変更"},{"id":"2","name":"2:検査依頼キャンセル"},{"id":"3","name":"3:検査依頼変更なし"},{"id":"4","name":"4:上記設定項目を手動で選択"}]', description='治療予定日変更時に紐付く検査依頼への処理を設定します。<br>1：変更された治療予定の日付に検査依頼の日付を変更します。<br>また、治療予定がキャンセルされた場合、検査依頼もキャンセルされます。<br>2：検査依頼をキャンセルします。<br>3：検査依頼への処理は行いません。<br>4：上記設定項目を手動で選択。' WHERE facility_setting_no='1007';
UPDATE ntss.sys_facility_setting SET setting_name='治療予定日変更時 一般撮影検査予定変更機能', option_value='[{"id":"1","name":"1:検査依頼を治療予定日に変更"},{"id":"2","name":"2:検査依頼キャンセル"},{"id":"3","name":"3:検査依頼変更なし"},{"id":"4","name":"4:上記設定項目を手動で選択"}]', description='治療予定日変更時に紐付く一般撮影検査依頼への処理を設定します。<br>1：変更された治療予定の日付に一般撮影検査依頼の日付を変更します。<br>また、治療予定がキャンセルされた場合、一般撮影検査依頼もキャンセルされます。<br>2：一般撮影検査依頼をキャンセルします。<br>3：一般撮影検査依頼は変更しません。<br>4：上記設定項目を手動で選択。' WHERE facility_setting_no='1008';
UPDATE ntss.sys_facility_setting SET setting_name='検査結果取込時連携コード選択', option_value='[{"id":"1","name":"1:連携コード１"},{"id":"2","name":"2:連携コード２"},{"id":"3","name":"3:連携コード３"}]', description='検査結果取込時に、各マスタを参照する際の連携コードを指定します。' WHERE facility_setting_no='1009';
UPDATE ntss.sys_facility_setting SET description='治療方法マスタに治療経過表を設定なしの場合、治療記録画面でデフォルト帳票を表示する。' WHERE facility_setting_no='3004';
UPDATE ntss.sys_facility_setting SET setting_name='治療予定日変更時 患者イベント変更機能', option_value='[{"id":"1","name":"1：患者イベントを治療予定日に変更"},{"id":"2","name":"2：患者イベント変更なし"},{"id":"3","name":"3：患者イベントキャンセル"},{"id":"4","name":"4：画面に手動選択"}]', description='治療予定日変更時に紐付く患者イベントへの処理を設定します。<br>1：変更された治療予定の日付に患者イベントの日付を変更します。<br>また、治療予定がキャンセルされた場合、患者イベントもキャンセルされます。<br>2：患者イベントへの処理は行いません。<br>3：患者イベントをキャンセルします。<br>4：画面に上記設定項目を手動選択する。' WHERE facility_setting_no='3005';
UPDATE ntss.sys_facility_setting SET description='いつまでの検査日を前回検査日とできる期間を設定します。<br>単位：日。' WHERE facility_setting_no='3012';
